275	    /**
276	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
277	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
278	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
279	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
280	     * segment of the owner's {@link #getMemberId() member id}.
281	     */
282	    @Transient
283	    public String getRegion() {
284	        return RegionPostcodeTable.regionOf(this.postcode)
285	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
