295	        if (this.memberId == null) {
296	            return getRegion();
297	        }
298	        return MemberId.regionOf(this.memberId);
299	    }
300	
301	    /**
302	     * The owner's IANA timezone name, derived on read from the owner's
303	     * {@link #getLocality() locality} via the fixed {@link RegionTimezoneTable}, e.g.
304	     * {@code "Australia/Sydney"} for {@code NSW}. {@code null} when the locality has no
305	     * timezone in the table.
306	     */
307	    @Transient
308	    public String getTimezone() {
309	        return RegionTimezoneTable.timezoneOf(getLocality());
310	    }
