322	    /**
323	     * The owner's identity key: the single value used to detect duplicate owners on
324	     * create. It is the lower-case SHA-256 hex digest of the owner's (already normalized)
325	     * telephone, lower-cased email and the {@link Soundex} code of its last name, joined
326	     * with {@code '|'} — {@code sha256(<telephone>|<lowerEmail>|<soundex(lastName)>)} — a
327	     * missing telephone or email contributing an empty segment. Two owners are duplicates
328	     * only when their whole identity keys are equal.
329	     */
330	    @Transient
331	    public String getIdentityKey() {
332	        String normalizedTelephone = orEmpty(this.telephone);
333	        String lowerEmail = orEmpty(this.email).toLowerCase(Locale.ROOT);
334	        String lastNameSoundex = Soundex.encode(getLastName());
335	        return Sha256Hex.hex(normalizedTelephone + "|" + lowerEmail + "|" + lastNameSoundex);
336	    }
