386	        return this.membershipLevel;
387	    }
388	
389	    public void setMembershipLevel(Integer membershipLevel) {
390	        this.membershipLevel = membershipLevel;
391	    }
392	
393	    /**
394	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, derived on read from
395	     * the owner's own fields (see {@link OwnerSegment}): the {@code TIER} is {@code PREMIUM}
396	     * when the owner's {@link #getMembershipLevel() membership level} is 3 or more, otherwise
397	     * {@code STANDARD}; the {@code AREA} is {@code METRO} when the owner's
398	     * {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
399	     * {@code REGIONAL}.
