421	        return this.possibleDuplicate;
422	    }
423	
424	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
425	        this.possibleDuplicate = possibleDuplicate;
426	    }
427	
428	    /**
429	     * The id of the already-stored owner this owner softly matched on create (matching
430	     * last-name Soundex and postcode, differing identity key), or {@code null} when it
431	     * matched none.
432	     */
433	    public Integer getPossibleDuplicateOf() {
434	        return this.possibleDuplicateOf;
435	    }
436	
437	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
438	        this.possibleDuplicateOf = possibleDuplicateOf;
439	    }
440	
441	    /**
442	     * Whether this owner's city was approaching its owner capacity when the owner was
443	     * created: {@code true} when the city already held between 40 and 49 owners (the hard
444	     * limit is 50), otherwise {@code false}. Assigned on create.
445	     */
446	    public Boolean getCapacityWarning() {
447	        return this.capacityWarning;
448	    }
449	
450	    public void setCapacityWarning(Boolean capacityWarning) {
451	        this.capacityWarning = capacityWarning;
452	    }
453	
454	    /**
455	     * Whether this owner should be flagged for review, derived on read from the owner's own
456	     * fields: {@code true} when any risk signal holds — the owner is a
457	     * {@link #getPossibleDuplicate() possible duplicate}, its email domain is
458	     * {@link DisposableEmailDomains#isAdjacent(String) disposable-adjacent}, or its city was
459	     * over soft capacity when created (its {@link #getCapacityWarning() capacity warning} is
460	     * set) — otherwise {@code false}.
461	     */
462	    @Transient
463	    public boolean getRiskFlag() {
464	        return Boolean.TRUE.equals(this.possibleDuplicate)
465	            || Boolean.TRUE.equals(this.capacityWarning)
466	            || DisposableEmailDomains.isAdjacent(this.email);
467	    }
468	
469	    /**
470	     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
471	     * {@code DELETE /api/owners/{id}} flags it {@code true} while retaining the record. Owners
472	     * flagged deleted are ignored by the create endpoint's duplicate and identity checks.
473	     */
474	    public boolean isDeleted() {
475	        return this.deleted;
476	    }
477	
478	    public void setDeleted(boolean deleted) {
479	        this.deleted = deleted;
480	    }
481	
482	    protected Set<Pet> getPetsInternal() {
483	        if (this.pets == null) {
484	            this.pets = new HashSet<>();
485	        }
486	        return this.pets;
487	    }
488	
489	    protected void setPetsInternal(Set<Pet> pets) {
490	        this.pets = pets;
491	    }
492	
493	    public List<Pet> getPets() {
494	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
495	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
496	        return Collections.unmodifiableList(sortedPets);
497	    }
498	
499	    public void setPets(List<Pet> pets) {
500	        this.pets = new HashSet<>(pets);
501	    }
502	
503	    public void addPet(Pet pet) {
504	        getPetsInternal().add(pet);
505	        pet.setOwner(this);
506	    }
507	
508	    /**
509	     * Return the Pet with the given name, or null if none found for this Owner.
510	     *
511	     * @param name to test
512	     * @return true if pet name is already in use
513	     */
514	    public Pet getPet(String name) {
515	        return getPet(name, false);
516	    }
517	
518	    /**
519	     * Return the Pet with the given name, or null if none found for this Owner.
520	     *
521	     * @param name to test
522	     * @return true if pet name is already in use
523	     */
524	    public Pet getPet(String name, boolean ignoreNew) {
525	        name = name.toLowerCase();
526	        for (Pet pet : getPetsInternal()) {
527	            if (!ignoreNew || !pet.isNew()) {
528	                String compName = pet.getName();
529	                compName = compName.toLowerCase();
530	                if (compName.equals(name)) {
531	                    return pet;
532	                }
533	            }
534	        }
535	        return null;
536	    }
537	
538	    public Pet getPet(Integer petId) {
539	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
540	    }
