193	        if (StringUtils.hasText(idempotencyKey)) {
194	            Owner original = this.idempotentOwnerStore.find(idempotencyKey)
195	                .map(this.clinicService::findOwnerById)
196	                .orElse(null);
197	            if (original != null) {
198	                return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
199	            }
200	        }
201	        HttpHeaders headers = new HttpHeaders();
202	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
203	        this.registrationDateAssigner.assign(owner);
204	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
205	            throw new CityAtCapacityException();
206	        }
207	        this.cityCapacityChecker.assignCapacityWarning(owner);
208	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
209	            throw new DailyRegistrationLimitException();
210	        }
211	        this.householdAssigner.assign(owner);
212	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
213	            throw new DuplicateOwnerException();
214	        }
215	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
216	        this.householdSizeAssigner.assign(owner);
217	        this.memberIdAssigner.assign(owner);
218	        this.namesakeCounter.assign(owner);
219	        this.membershipLevelAssigner.assign(owner);
220	        this.bulkSignupWarningAssigner.assign(owner);
221	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
222	        this.clinicService.saveOwner(owner);
223	        if (StringUtils.hasText(idempotencyKey)) {
224	            this.idempotentOwnerStore.remember(idempotencyKey, owner);
225	        }
226	        this.ownerCreationAuditLogger.logCreated(owner);
227	        this.welcomeNotifier.enqueueWelcome(owner);
228	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
